; zenpoint transcendentals: fp_ln, fp_exp, shared fp_poly / fp_scale2.
; SPDX-License-Identifier: Apache-2.0 OR GPL-2.0-only OR GPL-3.0-only OR MPL-2.0
; Copyright (c) 2026 haitch <h@ual.li>
;
; Mirrors tools/transc.py step for step (bit-exact by construction on
; the shared RNE cores). Constants/coefficients from src/lnexpconst.asm,
; generated by tools/gencoeff.py only.

; ======================================================================
; fp_poly: Horner evaluation. HL = table (count byte, then coefficients
; highest-degree first, 5 bytes each), DE = x ptr, IX = accumulator ptr.
; acc := P(x). No error paths (kernel domains are bounded by design).
; Does not touch IY.
; ======================================================================
fp_poly:
        ld b,(hl)
        inc hl
        ; acc = first coefficient
        push de
        push bc
        push ix
        pop de
        ld bc,5
        ldir                 ; also advances HL to the next coefficient
        pop bc
        pop de
        dec b
        ret z
fp_poly__loop:
        push hl              ; coeff cursor
        push de              ; x ptr
        push bc              ; count
        push ix
        pop hl
        call fp_mul          ; acc = acc * x   (HL=acc, DE=x, IX=acc)
        pop bc
        pop de
        pop hl
        push hl
        push de
        push bc
        ld d,h
        ld e,l               ; DE = coeff
        push ix
        pop hl
        call fp_add          ; acc = acc + coeff
        pop bc
        pop de
        pop hl
        inc hl
        inc hl
        inc hl
        inc hl
        inc hl
        djnz fp_poly__loop
        ret

; ======================================================================
; fp_scale2: scale the FP-form value at (HL) by 2^BC (BC signed 16-bit),
; in place. Zero stays zero; e <= 0 flushes to zero; e > 255 -> CF=1,
; A=1. Does not touch IY, DE, IX.
; ======================================================================
fp_scale2:
        ld a,(hl)
        or a
        jr nz,fp_scale2__fp
        ret                  ; canonical zero (int forms are not scaled
                             ; here by design; call sites are FP-only)
fp_scale2__fp:
        push hl
        push de
        ld l,a
        ld h,0               ; HL2 = e
        add hl,bc            ; e + delta (signed BC)
        bit 7,h
        jr nz,fp_scale2__uf  ; negative
        ld a,h
        or a
        jr nz,fp_scale2__of  ; >= 256
        ld a,l
        or a
        jr z,fp_scale2__uf   ; exactly 0
        pop de
        pop hl
        ld (hl),a
        or a
        ret
fp_scale2__uf:
        pop de
        pop hl
        push de
        xor a
        ld (hl),a
        inc hl
        ld (hl),a
        inc hl
        ld (hl),a
        inc hl
        ld (hl),a
        inc hl
        ld (hl),a
        pop de
        ; leave HL past the value; callers reload pointers from frames
        or a
        ret
fp_scale2__of:
        pop de
        pop hl
        ld a,1
        scf
        ret

; ======================================================================
; fp_ln: natural logarithm. HL = src, IX = result.
; CF=1, A=2 for x <= 0. Frame (IY+): 0..4 s, 5..9 z, 10..14 w,
; 15..19 acc, 20..24 kf, 25 k; saved IX at +26.
; ======================================================================
fp_ln:
        ; reject zero and negatives up front
        call is_zero_pk
        jr nz,fp_ln__nz
fp_ln__bad:
        ld a,2
        scf
        ret
fp_ln__nz:
        inc hl
        ld a,(hl)
        dec hl
        and 80h
        jr nz,fp_ln__bad     ; negative (both forms carry the bit/FFh)
        call unpack          ; B=e, C=0, DEHL=M (consumes HL)
        push ix              ; frame+30
        push de              ; M hi (frame+28)
        push hl              ; M lo (frame+26) -- the alloc clobbers HL
        ld hl,-26
        add hl,sp
        ld sp,hl
        ld iy,0
        add iy,sp
        ; s = [128, M...]; k = e - 128
        ld a,b
        sub 128
        ld (iy+25),a         ; k (signed)
        ld a,128
        ld (iy+0),a
        ld a,(iy+29)         ; D of M
        and 7Fh
        ld (iy+1),a
        ld a,(iy+28)         ; E
        ld (iy+2),a
        ld a,(iy+27)         ; H
        ld (iy+3),a
        ld a,(iy+26)         ; L
        ld (iy+4),a
        ; if s < sqrt2/2: s *= 2 (exponent bump), k -= 1
        push iy
        pop hl
        ld de,CSQRT2O2
        call fp_cmp
        bit 7,a
        jr z,fp_ln__srange
        ld a,129
        ld (iy+0),a
        dec (iy+25)
fp_ln__srange:
        ; z = (s - 1) / (s + 1)
        push iy
        pop hl               ; s
        ld de,CONE
        push iy
        pop ix
        ld bc,5
        add ix,bc            ; z buffer
        call fp_sub
        push iy
        pop hl
        ld de,CONE
        push iy
        pop ix
        ld bc,10
        add ix,bc            ; w buffer as temp for s+1
        call fp_add
        push iy
        pop hl
        ld bc,5
        add hl,bc            ; z
        push iy
        pop de
        push hl
        ld hl,10
        add hl,de
        ex de,hl             ; DE = w (s+1)
        pop hl
        push hl
        pop ix               ; IX = z (in place)
        call fp_div
        ; w = z * z
        push iy
        pop hl
        ld bc,5
        add hl,bc            ; z
        ld d,h
        ld e,l
        push iy
        pop ix
        ld bc,10
        add ix,bc            ; w
        call fp_mul
        ; acc = P(w)
        ld hl,LNPOLY_N
        push iy
        pop de
        push hl
        ld hl,10
        add hl,de
        ex de,hl             ; DE = w
        pop hl
        push iy
        pop ix
        ld bc,15
        add ix,bc            ; acc
        call fp_poly
        ; z *= 2 (exact)
        push iy
        pop hl
        ld bc,5
        add hl,bc
        ld bc,1
        call fp_scale2
        ; acc = z * acc
        push iy
        pop hl
        ld bc,5
        add hl,bc            ; z
        push iy
        pop de
        push hl
        ld hl,15
        add hl,de
        ex de,hl             ; DE = acc
        pop hl
        push iy
        pop ix
        ld bc,15
        add ix,bc            ; acc (in place)
        call fp_mul
        ; kf = int form of k
        ld a,(iy+25)
        ld c,a
        xor a
        ld (iy+20),a
        ld (iy+24),a
        bit 7,c
        jr z,fp_ln__kpos
        ld a,0FFh
fp_ln__kpos:
        ld (iy+21),a         ; sign byte 00/FF
        ld (iy+23),a         ; high byte of the 16-bit two's complement
        ld (iy+22),c         ; low byte
        ; kf = kf * ln2
        push iy
        pop hl
        ld bc,20
        add hl,bc
        ld de,CLN2
        push hl
        pop ix
        call fp_mul
        ; result = kf + acc (into acc, then copy out)
        push iy
        pop hl
        ld bc,20
        add hl,bc            ; kf
        push iy
        pop de
        push hl
        ld hl,15
        add hl,de
        ex de,hl             ; DE = acc
        pop hl
        push iy
        pop ix
        ld bc,15
        add ix,bc
        call fp_add          ; acc = kf + acc
        ; copy acc -> caller result (saved IX at frame+30)
        ld l,(iy+30)
        ld h,(iy+31)
        ld a,(iy+15)
        ld (hl),a
        inc hl
        ld a,(iy+16)
        ld (hl),a
        inc hl
        ld a,(iy+17)
        ld (hl),a
        inc hl
        ld a,(iy+18)
        ld (hl),a
        inc hl
        ld a,(iy+19)
        ld (hl),a
        ld hl,32             ; frame 26 + M 4 + saved IX 2
        add hl,sp
        ld sp,hl
        or a
        ret

; ======================================================================
; fp_exp: exponential. HL = src, IX = result.
; exp(0) = 1 (int form). Overflow: CF=1, A=1. Deep negative: 0.
; Frame (IY+): 0..4 t, 5..9 nf, 10..14 r, 15..19 acc, 20..21 n;
; saved IX at +22, saved x ptr at +24.
; ======================================================================
fp_exp:
        call is_zero_pk
        jr nz,fp_exp__nz
        ld (ix+0),0          ; exp(0) = 1, small-integer form
        ld (ix+1),0
        ld (ix+2),1
        ld (ix+3),0
        ld (ix+4),0
        or a
        ret
fp_exp__nz:
        ; magnitude pre-gate before any frame exists: FP form with
        ; e >= 136 (|x| >= 128), or int form whose high byte is not the
        ; sign extension (|x| >= 257), certainly overflows/underflows:
        ; positive -> CF=1 A=1; negative -> exp(x) flushes to 0.
        ld a,(hl)
        cp 136
        jp nc,fp_exp__gate
        or a
        jr nz,fp_exp__go
        push hl
        inc hl
        ld a,(hl)            ; sign byte
        inc hl
        inc hl
        cp (hl)              ; high byte == sign extension?
        pop hl
        jp nz,fp_exp__gate
fp_exp__go:
        push hl              ; x ptr (frame+24)
        push ix              ; result ptr (frame+22)
        ld hl,-22
        add hl,sp
        ld sp,hl
        ld iy,0
        add iy,sp
        ; t = x * (1/ln2)
        ld l,(iy+24)
        ld h,(iy+25)
        ld de,CINVLN2
        push iy
        pop ix               ; t buffer
        call fp_mul
        ; t += 0.5
        push iy
        pop hl
        ld de,CHALF
        push hl
        pop ix
        call fp_add
        ; nf = floor(t)
        push iy
        pop hl
        push iy
        pop ix
        ld bc,5
        add ix,bc            ; nf buffer
        call fp_int
        ; n (signed 16) from the int form [0, s, lo, hi, 0]
        ld c,(iy+7)
        ld b,(iy+8)          ; stored two's complement 16-bit
        ld (iy+20),c
        ld (iy+21),b
        ; range gate: n > 140 -> overflow; n < -140 -> zero result
        ld a,(iy+6)          ; sign byte
        or a
        jr nz,fp_exp__nneg
        ; positive: n > 140?
        ld a,b
        or a
        jp nz,fp_exp__of
        ld a,c
        cp 141
        jp nc,fp_exp__of
        jr fp_exp__reduce
fp_exp__nneg:
        ; negative: n < -140  <=>  u16 < 65396
        ld a,b
        cp 0FFh
        jp c,fp_exp__zero
        ld a,c
        cp 74h               ; 65396 & FF = 74h; hi is FFh here
        jp c,fp_exp__zero
fp_exp__reduce:
        ; r = (x - n*L1) - n*L2
        push iy
        pop hl
        ld bc,5
        add hl,bc            ; nf
        ld de,CL1
        push iy
        pop ix
        ld bc,15
        add ix,bc            ; acc = n*L1
        call fp_mul
        ld l,(iy+24)
        ld h,(iy+25)         ; x
        push iy
        pop de
        push hl
        ld hl,15
        add hl,de
        ex de,hl             ; DE = acc
        pop hl
        push iy
        pop ix
        ld bc,10
        add ix,bc            ; r buffer
        call fp_sub
        push iy
        pop hl
        ld bc,5
        add hl,bc            ; nf
        ld de,CL2
        push iy
        pop ix
        ld bc,15
        add ix,bc            ; acc = n*L2
        call fp_mul
        push iy
        pop hl
        ld bc,10
        add hl,bc            ; r
        push iy
        pop de
        push hl
        ld hl,15
        add hl,de
        ex de,hl             ; DE = acc
        pop hl
        push hl
        pop ix               ; r in place
        call fp_sub
        ; acc = Q(r)
        ld hl,EXPPOLY_N
        push iy
        pop de
        push hl
        ld hl,10
        add hl,de
        ex de,hl             ; DE = r
        pop hl
        push iy
        pop ix
        ld bc,15
        add ix,bc
        call fp_poly
        ; scale by 2^n
        push iy
        pop hl
        ld bc,15
        add hl,bc            ; acc
        ld c,(iy+20)
        ld b,(iy+21)
        call fp_scale2
        jr c,fp_exp__oferr   ; overflow during scale
        ; copy acc -> caller result
        ld l,(iy+22)
        ld h,(iy+23)
        ld a,(iy+15)
        ld (hl),a
        inc hl
        ld a,(iy+16)
        ld (hl),a
        inc hl
        ld a,(iy+17)
        ld (hl),a
        inc hl
        ld a,(iy+18)
        ld (hl),a
        inc hl
        ld a,(iy+19)
        ld (hl),a
fp_exp__done_ok:
        ld hl,26             ; frame 22 + ix 2 + x 2
        add hl,sp
        ld sp,hl
        or a
        ret
fp_exp__zero:
        ; write canonical zero to the caller result
        ld l,(iy+22)
        ld h,(iy+23)
        xor a
        ld (hl),a
        inc hl
        ld (hl),a
        inc hl
        ld (hl),a
        inc hl
        ld (hl),a
        inc hl
        ld (hl),a
        jr fp_exp__done_ok
fp_exp__of:
fp_exp__oferr:
        ld hl,26
        add hl,sp
        ld sp,hl
        ld a,1
        scf
        ret
fp_exp__gate:
        ; no frame allocated yet; HL = x, IX = caller result
        inc hl
        ld a,(hl)
        and 80h
        jr nz,fp_exp__gzero
        ld a,1               ; positive: overflow
        scf
        ret
fp_exp__gzero:
        ld (ix+0),0          ; negative: exp(x) -> 0
        ld (ix+1),0
        ld (ix+2),0
        ld (ix+3),0
        ld (ix+4),0
        or a
        ret
